package com.bolivariano.microservice.recbanred.core.configuration;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.apache.commons.lang3.StringUtils;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Configuration;
import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;

/**
 * Configuración de trama personalizada de infoReversal por empresa para reverso automático V2.
 *
 * Ejemplo en application.yml:
 *
 * auto-reversal-config:
 *   companies:
 *     - code: "2259"
 *       info-reversal-fields: "codAgencia,codLocalidad,billerAuthorizationCode,metodo_pago"
 *     - code: "8453"
 *       info-reversal-fields: "codAgencia,billerAuthorizationCode,metodo_pago"
 */
@Configuration
@Component
@Data
@ConfigurationProperties(prefix = "auto-reversal-config")
@AllArgsConstructor
@NoArgsConstructor
public class AutoReversalConfiguration {

    private List<CompanyReversalConfig> companies = Collections.emptyList();

    /**
     * Busca la configuración de una empresa por su código.
     * Devuelve empty si la empresa no está configurada.
     */
    public Optional<CompanyReversalConfig> findByCompanyCode(String companyCode) {
        if (StringUtils.isEmpty(companyCode) || companies == null) return Optional.empty();
        return companies.stream()
                .filter(c -> companyCode.equals(c.getCode()))
                .findFirst();
    }

    @Data
    @AllArgsConstructor
    @NoArgsConstructor
    public static class CompanyReversalConfig {

        /** Código de empresa (codigoEmpresa del servicio) */
        private String code;

        /**
         * Campos que irán en infoReversal, en el orden definido aquí.
         * Separados por coma. Ej: "codAgencia,codLocalidad,billerAuthorizationCode,metodo_pago"
         */
        private String infoReversalFields;

        /**
         * Devuelve la lista de campos en el orden configurado.
         */
        public List<String> getInfoReversalFieldList() {
            if (StringUtils.isEmpty(infoReversalFields)) return Collections.emptyList();
            return Stream.of(infoReversalFields.split(","))
                    .map(String::trim)
                    .toList();
        }
    }
}

package com.bolivariano.microservice.recbanred.core.configuration;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.apache.commons.lang3.StringUtils;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Configuration;
import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Stream;

/**
 * Configuración de trama personalizada de infoReversal por empresa para reverso automático V2.
 *
 * Ejemplo en application.yml:
 *
 * auto-reversal-config:
 *   companies:
 *     - code: "2259"
 *       reversal-types: "A,M"
 *       info-reversal-fields: "codAgencia,codLocalidad,billerAuthorizationCode,metodo_pago"
 *     - code: "8453"
 *       reversal-types: "A"
 *       info-reversal-fields: "codAgencia,billerAuthorizationCode,metodo_pago"
 */
@Configuration
@Component
@Data
@ConfigurationProperties(prefix = "auto-reversal-config")
@AllArgsConstructor
@NoArgsConstructor
public class AutoReversalConfiguration {

    private List<CompanyReversalConfig> companies = Collections.emptyList();

    /**
     * Busca la configuración de una empresa por su código.
     * Devuelve empty si la empresa no está configurada.
     */
    public Optional<CompanyReversalConfig> findByCompanyCode(String companyCode) {
        if (StringUtils.isEmpty(companyCode) || companies == null) return Optional.empty();
        return companies.stream()
                .filter(c -> companyCode.equals(c.getCode()))
                .findFirst();
    }

    @Data
    @AllArgsConstructor
    @NoArgsConstructor
    public static class CompanyReversalConfig {

        /** Código de empresa (codigoEmpresa del servicio) */
        private String code;

        /**
         * Tipos de reverso que usarán trama personalizada para esta empresa.
         * Valores permitidos: A, M. Separados por coma. Ej: "A,M"
         * Si no se define, se mantiene compatibilidad usando solo "A".
         */
        private String reversalTypes;

        /**
         * Campos que irán en infoReversal, en el orden definido aquí.
         * Separados por coma. Ej: "codAgencia,codLocalidad,billerAuthorizationCode,metodo_pago"
         */
        private String infoReversalFields;

        /**
         * Devuelve la lista de campos en el orden configurado.
         */
        public List<String> getInfoReversalFieldList() {
            if (StringUtils.isEmpty(infoReversalFields)) return Collections.emptyList();
            return Stream.of(infoReversalFields.split(","))
                    .map(String::trim)
                    .toList();
        }

        /**
         * Determina si la empresa tiene habilitado el tipo de reverso para trama personalizada.
         */
        public boolean supportsReversalType(String reversalType) {
            if (StringUtils.isEmpty(reversalType)) return false;

            String configuredTypes = StringUtils.isEmpty(reversalTypes) ? "A" : reversalTypes;
            Set<String> allowedTypes = Stream.of(configuredTypes.split(","))
                    .map(String::trim)
                    .filter(StringUtils::isNotEmpty)
                    .map(String::toUpperCase)
                    .collect(java.util.stream.Collectors.toSet());

            return allowedTypes.contains(reversalType.trim().toUpperCase());
        }
    }
}

package com.bolivariano.microservice.recbanred.core.configuration;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Configuration;
import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.List;

@Configuration
@Component
@Data
@ConfigurationProperties(prefix = "data-masking")
@AllArgsConstructor
@NoArgsConstructor
public class DataMaskingConfiguration {

    /** Activa o desactiva el enmascaramiento de datos sensibles */
    private boolean enabled;

    /** Códigos de campos adicionales (DatoAdicional.codigo) que deben enmascararse */
    private List<String> sensitiveFieldCodes = Collections.emptyList();

    /**
     * Longitud máxima permitida para cualquier valor de campo genérico.
     * Previene ataques de desbordamiento de buffer / DoS.
     * Default: 500
     */
    private int maxFieldLength = 500;

    /**
     * Longitud máxima permitida para campos clave de cabecera (secuencial, transaccion, usuario).
     * Default: 100
     */
    private int maxKeyFieldLength = 500;
}

package com.bolivariano.microservice.recbanred.core.configuration;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Configuration;
import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.List;

@Configuration
@Component
@Data
@ConfigurationProperties(prefix = "data-masking")
@AllArgsConstructor
@NoArgsConstructor
public class DataMaskingConfiguration {

    /** Activa o desactiva sanitización, validación y enmascaramiento del flujo de consulta */
    private boolean enabled;

    /** Códigos de campos adicionales (DatoAdicional.codigo) que deben enmascararse */
    private List<String> sensitiveFieldCodes = Collections.emptyList();

    /**
     * Longitud máxima permitida para cualquier valor de campo genérico.
     * Previene ataques de desbordamiento de buffer / DoS.
     * Default: 500
     */
    private int maxFieldLength = 500;

    /**
     * Longitud máxima permitida para campos clave de cabecera (secuencial, transaccion, usuario).
     * Default: 100
     */
    private int maxKeyFieldLength = 500;
}

package com.bolivariano.microservice.recbanred.util;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.apache.commons.lang3.StringUtils;
import org.owasp.encoder.Encode;
import org.slf4j.MDC;

public class LoggingContext {

    private LoggingContext() {}

    public static final String UID = "uid";
    public static final String COMPANY_CODE = "codEmpresa";
    public static final String SEQUENTIAL_BANK = "secuencial";
    public static final String FLUX_TYPE = "tipoFlujo";

    private static final ObjectMapper LOG_OBJECT_MAPPER = new ObjectMapper()
            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false)
            //  No revienta con beans vacíos (muy común en proxies)
            .configure(SerializationFeature.FAIL_ON_EMPTY_BEANS, false)
            //Fechas en ISO-8601, no timestamps
            .configure(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false)
            //No escribe zonas raras
            .configure(SerializationFeature.WRITE_DATES_WITH_ZONE_ID, false)
            //Evita excepciones por propiedades problemáticas
            .configure(SerializationFeature.FAIL_ON_SELF_REFERENCES, false)
            //Manejo correcto de Java Time
            .registerModule(new JavaTimeModule());

    public static void init(String uid, String tipoFlujo, String codigoEmpresa, String secuencialBanco) {
        MDC.put(UID, uid);
        MDC.put(COMPANY_CODE, codigoEmpresa);
        MDC.put(FLUX_TYPE, tipoFlujo);
        MDC.put(SEQUENTIAL_BANK, secuencialBanco);
    }

    public static void clear() {
        MDC.clear();
    }

    public static String sanitize(String input) {
        if (input == null) return null;
        return Encode.forJava(input)
                .replace("\\\"", "\"")
                .replace("\\n", "")
                .replace("\\r", "")
                .replace("\\t", "")
                .replaceAll("[\\x00-\\x1F]", "");
    }

    public static String writeJsonLogAndSanitize(Object input) {
        try {
            return sanitize(LOG_OBJECT_MAPPER.writeValueAsString(input));
        } catch (JsonProcessingException e) {
            return StringUtils.EMPTY;
        }
    }}

package com.bolivariano.microservice.recbanred.util;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.apache.commons.lang3.StringUtils;
import org.owasp.encoder.Encode;
import org.slf4j.MDC;

public class LoggingContext {

    private LoggingContext() {}

    public static final String UID = "uid";
    public static final String COMPANY_CODE = "codEmpresa";
    public static final String SEQUENTIAL_BANK = "secuencial";
    public static final String FLUX_TYPE = "tipoFlujo";
    public static final String CHANNEL = "canal";
    public static final String SERVICE_TYPE = "codTipoServicio";
    public static final String IDENTIFIER = "identificador";

    private static final ObjectMapper LOG_OBJECT_MAPPER = new ObjectMapper()
            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false)
            //  No revienta con beans vacíos (muy común en proxies)
            .configure(SerializationFeature.FAIL_ON_EMPTY_BEANS, false)
            //Fechas en ISO-8601, no timestamps
            .configure(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false)
            //No escribe zonas raras
            .configure(SerializationFeature.WRITE_DATES_WITH_ZONE_ID, false)
            //Evita excepciones por propiedades problemáticas
            .configure(SerializationFeature.FAIL_ON_SELF_REFERENCES, false)
            //Manejo correcto de Java Time
            .registerModule(new JavaTimeModule());

    public static void init(String uid, String tipoFlujo, String codigoEmpresa, String secuencialBanco) {
        MDC.put(UID, uid);
        MDC.put(COMPANY_CODE, codigoEmpresa);
        MDC.put(FLUX_TYPE, tipoFlujo);
        MDC.put(SEQUENTIAL_BANK, secuencialBanco);
    }

    public static void putRequestContext(String canal, String codTipoServicio, String identificador) {
        MDC.put(CHANNEL, StringUtils.defaultString(canal));
        MDC.put(SERVICE_TYPE, StringUtils.defaultString(codTipoServicio));
        MDC.put(IDENTIFIER, StringUtils.defaultString(identificador));
    }

    public static void clear() {
        MDC.clear();
    }

    public static String sanitize(String input) {
        if (input == null) return null;
        return Encode.forJava(input)
                .replace("\\\"", "\"")
                .replace("\\n", "")
                .replace("\\r", "")
                .replace("\\t", "")
                .replaceAll("[\\x00-\\x1F]", "");
    }

    public static String writeJsonLogAndSanitize(Object input) {
        try {
            return sanitize(LOG_OBJECT_MAPPER.writeValueAsString(input));
        } catch (JsonProcessingException e) {
            return StringUtils.EMPTY;
        }
    }}

package com.bolivariano.microservice.recbanred.core.payloads.output;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class MensajeSalidaProcesarTest {

    private final ObjectMapper objectMapper = new ObjectMapper();

    @Test
    void shouldSerializeCodigoPropertyWithoutResponseCodeField() throws Exception {
        MensajeSalidaProcesar response = new MensajeSalidaProcesar().success();

        String json = objectMapper.writeValueAsString(response);

        assertTrue(json.contains("\"codigo\":\"0\""));
        assertFalse(json.contains("responseCode"));
    }
}
